import React, { useState } from 'react';
import './Dashboard.css'; // Import CSS for styling
import companyLogo from './images/cadmax.png'; // Path to the company logo


const CustomerDashboard = () => {
  const [activeTab, setActiveTab] = useState('customer'); // State to track active tab
  const [showNewCustomerForm, setShowNewCustomerForm] = useState(false); // State to toggle new customer form
  const [selectedDepartment, setSelectedDepartment] = useState(''); // State to track the selected department
  const [formData, setFormData] = useState({});
  const [showConfirmationPopup, setShowConfirmationPopup] = useState(false); // State for showing confirmation popup

  // State to store new customer form data
  const [customerData, setCustomerData] = useState({
    name: '',
    company: '',
    contact: '',
    address: ''
  });

  // Function to handle tab change
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setShowNewCustomerForm(false); // Ensure the new customer form is hidden when changing tabs
    setSelectedDepartment(''); // Reset department selection
    setFormData({});
  };

  // Toggle between customer selection and new customer form
  const toggleNewCustomerForm = () => {
    setShowNewCustomerForm(!showNewCustomerForm);
  };

  // Handle department selection for the "Working" tab
  const handleDepartmentChange = (event) => {
    setSelectedDepartment(event.target.value);
    setFormData({});
  };

  const handleInputChange = (event, field) => {
    setFormData({
      ...formData,
      [field]: event.target.value,
    });
  };

  // Handle confirmation of the form submission
  const handleSubmit = () => {
    setShowConfirmationPopup(true); // Show confirmation popup
  };

  // Handle the action when user confirms the submission
  const handleConfirmSubmit = () => {
    setShowConfirmationPopup(false); // Close the confirmation popup
    alert('Form submitted successfully!'); // You can replace this with actual form submission logic
  };

  // Handle the action when user cancels the submission
  const handleCancelSubmit = () => {
    setShowConfirmationPopup(false); // Close the confirmation popup
  };

  const renderFormFields = () => {
    switch (selectedDepartment) {
      case 'Survey Department':
        return (
          <>
            <div className="form-group">
              <label>Type of Survey</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Type of Survey')} />
            </div>
            <div className="form-group">
              <label>Khasra No</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Khasra No')} />
            </div>
            <div className="form-group">
              <label>Area</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Area')} />
            </div>
            <div className="form-group">
              <label>Demarcation</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Demarcation')} />
            </div>
            <div className="form-group">
              <label>Total Cost</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Total Cost')} />
            </div>
            <div className="form-group">
              <label>Remarks</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Remarks')} />
            </div>
          </>
        );
      case 'Architecture Department':
        return (
          <>
            <div className="form-group">
              <label>Type of Architectural Work</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Type of Architectural Work')} />
            </div>
            <div className="form-group">
              <label>Demarcation</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Demarcation')} />
            </div>
            <div className="form-group">
              <label>Total Cost</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Total Cost')} />
            </div>
            <div className="form-group">
              <label>Remarks</label>
              <input type="text" onChange={(e) => handleInputChange(e, 'Remarks')} />
            </div>
          </>
        );
      // Add more cases for each department as needed
      default:
        return null;
    }
  };


  return (
    <div className="dashboard-layout">
      {/* Sidebar */}
      <div className="sidebar">
        <div className="logo-container">
          <img src={companyLogo} alt="Company Logo" className="company-logo" />
        </div>
        <nav className="nav-links">
          <a
            href="#customer"
            className={`nav-link ${activeTab === 'customer' ? 'active' : ''}`}
            onClick={() => handleTabChange('customer')}
          >
            Customer
          </a>
          <a
            href="#working"
            className={`nav-link ${activeTab === 'working' ? 'active' : ''}`}
            onClick={() => handleTabChange('working')}
          >
            Working
          </a>
          <a
            href="#attendance"
            className={`nav-link ${activeTab === 'attendance' ? 'active' : ''}`}
            onClick={() => handleTabChange('attendance')}
          >
            Attendance
          </a>
        </nav>
      </div>

      {/* Main Content */}
      <div className="main-content">
        <header className="header">
          <h1 className="company-title">CadMax Projects Pvt. Ltd.</h1>
          <div className="profile-container">
            <span className="profile-name">Username</span>
            <span className="profile-emoji" role="img" aria-label="Profile">👤</span> {/* Emoji added */}
          </div>
        </header>

        {/* Conditionally Render Content based on activeTab */}
        <div className="content-container">
          {/* Customer Tab */}
          {activeTab === 'customer' && !showNewCustomerForm && (
            <div className="customer-box">
              <label htmlFor="existing-customer" className="select-label">
                Select Existing Customer
              </label>
              <select id="existing-customer" className="select-customer">
                <option>Search...</option>
                <option>Customer A</option>
                <option>Customer B</option>
                <option>Customer C</option>
                <option>Customer D</option>
                <option>Customer E</option>
              </select>
              <div className="or-divider">
                <span>or</span>
              </div>
              <button className="add-customer-btn" onClick={toggleNewCustomerForm}>
                Add a new customer
              </button>
            </div>
          )}

          {/* New Customer Form */}
          {showNewCustomerForm && (
            <div className="new-customer-form">
              <h3>Register New Customer</h3>
              <div className="form-group">
                <label>Name</label>
                <input
                  type="text"
                  name="name"
                  className="form-input"
                  placeholder="Enter Name"
                  value={customerData.name}
                  onChange={handleInputChange}
                />
              </div>
              <div className="form-group">
                <label>Company</label>
                <input
                  type="text"
                  name="company"
                  className="form-input"
                  placeholder="Enter Company"
                  value={customerData.company}
                  onChange={handleInputChange}
                />
              </div>
              <div className="form-group">
                <label>Contact Number</label>
                <input
                  type="text"
                  name="contact"
                  className="form-input"
                  placeholder="Enter Contact Number"
                  value={customerData.contact}
                  onChange={handleInputChange}
                />
              </div>
              <div className="form-group">
                <label>Address</label>
                <input
                  type="text"
                  name="address"
                  className="form-input"
                  placeholder="Enter Address"
                  value={customerData.address}
                  onChange={handleInputChange}
                />
              </div>
              <button className="submit-btn" onClick={handleSubmit}>
                Submit
              </button>
              <button className="back-btn" onClick={toggleNewCustomerForm}>
                Back to Customer Selection
              </button>
            </div>
          )}

          {/* Confirmation Popup */}
          {showConfirmationPopup && (
            <div className="confirmation-popup">
              <div className="popup-content">
                <h3>Are you sure you want to submit the customer details?</h3>
                <p><strong>Name:</strong> {customerData.name}</p>
                <p><strong>Company:</strong> {customerData.company}</p>
                <p><strong>Contact Number:</strong> {customerData.contact}</p>
                <p><strong>Address:</strong> {customerData.address}</p>
                <button className="confirm-btn" onClick={handleConfirmSubmit}>
                  Confirm
                </button>
                <button className="cancel-btn" onClick={handleCancelSubmit}>
                  Cancel
                </button>
              </div>
            </div>
          )}


          {/* Working Tab */}
          {activeTab === 'working' && (
            <div className="working-box">
              <div className="working-content">
                <label htmlFor="select-department" className="select-label">
                  Choose Department:
                </label>
                <select
                  id="select-department"
                  className="select-department"
                  value={selectedDepartment}
                  onChange={handleDepartmentChange}
                >
                  <option value="">Select Department...</option>
                  <option value="Survey Department">Survey Department</option>
                  <option value="Architecture Department">Architecture Department</option>
                  <option value="Urban Planning Department">Urban Planning Department</option>
                  <option value="Engineering Drawing Department">Engineering Drawing Department</option>
                  <option value="JDA Submission">JDA Submission</option>
                  <option value="GIS">GIS</option>
                  <option value="Site Plan">Site Plan</option>
                  <option value="Area Conversion">Area Conversion</option>
                  <option value="Sector SuperImpose">Sector SuperImpose</option>
                  <option value="Print">Print</option>
                </select>
                {selectedDepartment && (
                  <div className="department-form">
                    <h3>{selectedDepartment} Form</h3>
                    {renderFormFields()}
                    <button className="submit-btn" onClick={handleSubmit}>
                      Submit
                  </button>
                  </div>
                )}
              </div>
            </div>
          )}

          {showConfirmationPopup && (
            <div className="confirmation-popup">
              <div className="popup-content">
                <h3>Are you sure you want to submit the details?</h3>
                {Object.entries(formData).map(([key, value]) => (
                  <p key={key}>
                    <strong>{key}:</strong> {value}
                  </p>
                ))}
                <button className="confirm-btn" onClick={handleConfirmSubmit}>
                  Confirm
              </button>
                <button className="cancel-btn" onClick={handleCancelSubmit}>
                  Cancel
              </button>
              </div>
            </div>
          )}
        </div>
      </div>
      )}
        </div>
  )
}
   

export default CustomerDashboard;
